// Package config describes the relay daemon's configuration and how it is read and written.
//
// No app secrets live here — only the relay's own parameters: the origin to proxy to, the Reality
// keys (obfuscation), TURN settings and the publishing mode. The file is generated by the `setup`
// wizard and can be edited by hand afterwards.
package config

import (
	"fmt"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"strings"

	"github.com/BurntSushi/toml"
)

// DefaultPath — where the daemon looks for its configuration when no path is given by a flag.
const DefaultPath = "/etc/ringly-relay/config.toml"

// Config — the daemon's root configuration.
type Config struct {
	Origin   Origin   `toml:"origin"`
	Bridge   Bridge   `toml:"bridge"`
	Reality  Reality  `toml:"reality"`
	Calls    Calls    `toml:"calls"`
	Publish  Publish  `toml:"publish"`
	Operator Operator `toml:"operator"`

	// StatePath — the daemon's state file (its registration token in the pool). Not a setting but
	// something the daemon writes itself, so it is not serialized into the configuration; main sets
	// the path (next to the configuration or RINGLY_RELAY_STATE_DIR).
	StatePath string `toml:"-"`
}

// Origin — where the bridge sends traffic once the obfuscation layer is removed (the content itself
// stays end-to-end encrypted; the daemon only sees the app's ciphertext). Control — where the daemon
// registers.
type Origin struct {
	URL     string `toml:"url"`     // e.g. https://api.ringlyapp.net
	Control string `toml:"control"` // where to auto-publish; usually the same as URL
}

// Bridge — the message bridge: an obfuscated VLESS+Reality entry point (terminated by sing-box),
// traffic goes to the origin the client asked for. SingboxPath — the sing-box binary the daemon
// supervises (not embedded as a library: the reference implementation is more reliable and easier to
// audit).
type Bridge struct {
	Enabled     bool   `toml:"enabled"`
	Listen      string `toml:"listen"`       // e.g. ":443" — looks like HTTPS
	SingboxPath string `toml:"singbox_path"` // path to sing-box; taken from PATH by default
}

// Reality — VLESS+Reality obfuscation parameters. The private key and UUID are generated by `setup`.
// PublicKey is derived from the private one and not stored (`link` prints it, registration sends it).
type Reality struct {
	SNI        string `toml:"sni"`         // borrowed cover domain (real and reachable)
	PrivateKey string `toml:"private_key"` // X25519, base64url (raw)
	ShortID    string `toml:"short_id"`    // hex
	UUID       string `toml:"uuid"`        // VLESS user id
}

// Calls — the call relay (TURN). Off by default: all voice and video pass through it.
//
// Secret — the shared REST authentication secret (coturn-compatible scheme: the client gets temporary
// credentials username="<expiry>[:uid]", password=base64(HMAC-SHA1(secret, username))). PublicIP is
// REQUIRED behind NAT: without it the relay hands out an internal address and connections hang.
type Calls struct {
	Enabled       bool   `toml:"enabled"`
	TurnListen    string `toml:"turn_listen"`     // UDP+TCP, e.g. ":3478"
	TurnTLSListen string `toml:"turn_tls_listen"` // TURN over TLS, e.g. ":5349" (fallback when UDP is throttled)
	TrafficCapGB  int    `toml:"traffic_cap_gb"`  // monthly limit; 0 = unlimited
	Secret        string `toml:"secret"`          // REST auth secret (generated by setup)
	PublicIP      string `toml:"public_ip"`       // public IP for relay addresses (required behind NAT)
	TLSCert       string `toml:"tls_cert"`        // certificate for TURN over TLS (optional; self-signed otherwise)
	TLSKey        string `toml:"tls_key"`         // its key
}

// Publish — how the daemon gets into the pool.
//
//	auto    — auto-publishing on Origin.Control, the server hands the bridge out to users;
//	private — the server does not know about the daemon; `link` prints a link you share yourself.
//
// EnrollSecret — the shared registration secret; a barrier against accidental pool spam. It is built
// into the daemon (DefaultEnrollSecret) and never asked for: a volunteer has nowhere to get it from.
// PublicHost — the public host/IP to register; when empty the server uses the request's IP.
type Publish struct {
	Mode         string `toml:"mode"`
	EnrollSecret string `toml:"enroll_secret"`
	PublicHost   string `toml:"public_host"`
}

// Operator — an optional operator contact (for reaching the volunteer; never shown to users).
type Operator struct {
	Contact string `toml:"contact"`
}

const (
	ModeAuto    = "auto"
	ModePrivate = "private"
)

// DefaultEnrollSecret — the shared pool registration secret built into the daemon. It is in the open
// code on purpose: it does not stop a targeted attack, it only filters accidental spam into the pool.
// The real protection of bridge distribution is on the server (Google/Apple sign-in + cohorts).
// Must match RELAY_ENROLL_SECRET in the backend's .env; change both at once (daemons with the old
// value stop registering).
const DefaultEnrollSecret = "d813a45b5eee8c0a64f74104d788feb95f2ec4c707614255"

// DefaultSNI — the cover domain offered by setup. Not www.microsoft.com: with it the Reality handshake
// failed for every client (sing-box and Xray alike) although the domain opened over TLS 1.3.
const DefaultSNI = "dl.google.com"

// Default returns a configuration with default values (before the wizard fills it in).
func Default() Config {
	return Config{
		Origin: Origin{
			URL:     "https://api.ringlyapp.net",
			Control: "https://api.ringlyapp.net",
		},
		Bridge: Bridge{
			Enabled:     true,
			Listen:      ":443",
			SingboxPath: "sing-box",
		},
		Reality: Reality{
			SNI: DefaultSNI,
		},
		Calls: Calls{
			Enabled:       false,
			TurnListen:    ":3478",
			TurnTLSListen: ":5349",
			TrafficCapGB:  100,
		},
		Publish: Publish{Mode: ModeAuto, EnrollSecret: DefaultEnrollSecret},
	}
}

// Load reads the configuration from a file.
func Load(path string) (Config, error) {
	var c Config
	if _, err := toml.DecodeFile(path, &c); err != nil {
		return Config{}, fmt.Errorf("reading configuration %s: %w", path, err)
	}
	// configurations created before the secret was built in don't have it; nobody will type it in
	if c.Publish.EnrollSecret == "" {
		c.Publish.EnrollSecret = DefaultEnrollSecret
	}
	return c, nil
}

// Save writes the configuration atomically: first to a temporary file next to it, then rename — so an
// interrupted write never leaves a half-written configuration the daemon can't start with.
func Save(path string, c Config) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("creating the configuration directory: %w", err)
	}
	tmp, err := os.CreateTemp(filepath.Dir(path), ".config-*.toml")
	if err != nil {
		return fmt.Errorf("temporary configuration file: %w", err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName) // in case of an error before rename

	if err := toml.NewEncoder(tmp).Encode(c); err != nil {
		tmp.Close()
		return fmt.Errorf("serializing the configuration: %w", err)
	}
	if err := tmp.Close(); err != nil {
		return fmt.Errorf("closing the temporary configuration: %w", err)
	}
	if err := os.Chmod(tmpName, 0o600); err != nil { // the Reality private key — owner only
		return fmt.Errorf("configuration permissions: %w", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		return fmt.Errorf("replacing the configuration: %w", err)
	}
	return nil
}

// PortFromListen extracts the port number from a string like ":443" or "0.0.0.0:443".
func PortFromListen(listen string) (int, error) {
	l := listen
	if strings.HasPrefix(l, ":") {
		l = "0.0.0.0" + l
	}
	_, portStr, err := net.SplitHostPort(l)
	if err != nil {
		return 0, fmt.Errorf("can't parse a port from %q: %w", listen, err)
	}
	port, err := strconv.Atoi(portStr)
	if err != nil {
		return 0, fmt.Errorf("port %q is not a number: %w", portStr, err)
	}
	return port, nil
}

// Validate checks that the configuration is consistent enough to start.
func (c Config) Validate() error {
	if !c.Bridge.Enabled && !c.Calls.Enabled {
		return fmt.Errorf("no module is enabled (bridge or calls) — the daemon has nothing to do")
	}
	if c.Bridge.Enabled {
		if c.Origin.URL == "" {
			return fmt.Errorf("bridge is enabled but origin.url is empty")
		}
		if err := ValidateURL(c.Origin.URL); err != nil {
			return fmt.Errorf("origin.url: %w", err)
		}
		if c.Reality.PrivateKey == "" || c.Reality.ShortID == "" || c.Reality.UUID == "" {
			return fmt.Errorf("bridge is enabled but the Reality keys are not set — run `ringly-relay setup`")
		}
		if err := validatePrivateKey(c.Reality.PrivateKey); err != nil {
			return err
		}
		if !shortIDRe.MatchString(c.Reality.ShortID) {
			return fmt.Errorf("reality.short_id %q is invalid (even-length hex, up to 16 characters) — remove the keys and run `ringly-relay setup`", c.Reality.ShortID)
		}
		if !uuidRe.MatchString(c.Reality.UUID) {
			return fmt.Errorf("reality.uuid %q is invalid — remove the keys and run `ringly-relay setup`", c.Reality.UUID)
		}
		if c.Reality.SNI == "" {
			return fmt.Errorf("bridge is enabled but reality.sni is empty")
		}
		if err := ValidateHost(c.Reality.SNI); err != nil {
			return fmt.Errorf("reality.sni: %w", err)
		}
		if err := validateListen("bridge.listen", c.Bridge.Listen); err != nil {
			return err
		}
	}
	if c.Calls.Enabled {
		if c.Calls.Secret == "" {
			return fmt.Errorf("calls is enabled but the secret is not set — run `ringly-relay setup`")
		}
		if c.Calls.PublicIP == "" {
			return fmt.Errorf("calls is enabled but public_ip is not set — behind NAT the relay doesn't work without it")
		}
		if net.ParseIP(c.Calls.PublicIP) == nil {
			return fmt.Errorf("calls.public_ip %q — an IP address is required, e.g. 203.0.113.10", c.Calls.PublicIP)
		}
		if err := validateListen("calls.turn_listen", c.Calls.TurnListen); err != nil {
			return err
		}
		if (c.Calls.TLSCert == "") != (c.Calls.TLSKey == "") {
			return fmt.Errorf("TURN over TLS needs both tls_cert and tls_key (or neither — then a self-signed one is used)")
		}
	}
	switch c.Publish.Mode {
	case ModeAuto:
		if c.Origin.Control == "" {
			return fmt.Errorf("publish.mode=auto but origin.control is empty")
		}
		if err := ValidateURL(c.Origin.Control); err != nil {
			return fmt.Errorf("origin.control: %w", err)
		}
		if c.Publish.EnrollSecret == "" {
			return fmt.Errorf("publish.mode=auto but publish.enroll_secret is empty — set the registration secret")
		}
	case ModePrivate:
		// fine — no registration, the bridge is shared by a link
	default:
		return fmt.Errorf("unknown publish.mode=%q (expected auto|private)", c.Publish.Mode)
	}
	return nil
}
